contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // Parameterised: if the arrays are empty, don't call (avoid trivial setup).
        // Otherwise, transfer must succeed or fail based on v length.
        require(_tos.length > 0);
        require(v.length == _tos.length);

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if all v are greater than zero and lengths match,
        // then the call should not revert (a successful path exists).
        assert(reverted || !allPositive(v));
    }

    function allPositive(uint[] memory v) internal pure returns (bool) {
        for (uint i = 0; i < v.length; i++) {
            if (v[i] == 0) return false;
        }
        return true;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(v.length == _tos.length);

        bool allPositive = true;
        for (uint i = 0; i < v.length; i++) {
            if (v[i] == 0) { allPositive = false; break; }
        }

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(allPositive ? !reverted : true);
    }
}

